// The query executed by GetConversationAnalysis.
const GetConversationAnalysis_Operation = `
query GetConversationAnalysis ($agentId: ID!, $conversationId: ID!, $first: Int!, $after: String) {
	organization {
		agent(id: $agentId) {
			__typename
			id
			name
			conversationV2(id: $conversationId) {
				id
				title
				messages(first: $first, after: $after) {
					total
					pageInfo {
						hasNextPage
						endCursor
					}
					edges {
						cursor
						node {
							__typename
							... on AgentConversationUserMessageEvent {
								id
								content
								createdAt
							}
							... on AgentConversationAssistantMessageEvent {
								id
								content
								createdAt
								toolCalls {
									toolCallId
									name
									displayName
									arguments {
										__typename
										... on ValidToolCallArguments {
											jsonValues {
												name
												value
											}
										}
										... on InvalidToolCallArguments {
											invalidJson
										}
									}
								}
							}
							... on AgentConversationToolStartMessageEvent {
								id
								message
								createdAt
								toolCallId
							}
							... on AgentConversationToolCompleteMessageEvent {
								id
								createdAt
								toolCallId
							}
							... on AgentConversationToolErrorMessageEvent {
								id
								createdAt
								toolCallId
								errorMessage
							}
							... on AgentConversationToolMessageEvent {
								id
								createdAt
								toolResponses {
									toolCallId
									name
									displayName
									responseData
								}
							}
							... on AgentConversationSystemMessageEvent {
								id
								content
								createdAt
							}
						}
					}
				}
			}
		}
	}
}
`

