// The query executed by ListAspectRecords.
const ListAspectRecords_Operation = `
query ListAspectRecords ($aspectId: ID!, $first: Int, $after: String) {
	organization {
		aspect(id: $aspectId) {
			id
			name
			__typename
			... on AspectApp {
				namespace
				records(first: $first, after: $after) {
					edges {
						node {
							__typename
							... RecordListItem
						}
						cursor
					}
					pageInfo {
						hasNextPage
						endCursor
					}
					total
				}
			}
			... on AspectElement {
				namespace
				records(first: $first, after: $after) {
					edges {
						node {
							__typename
							... RecordListItem
						}
						cursor
					}
					pageInfo {
						hasNextPage
						endCursor
					}
					total
				}
			}
			... on AspectTask {
				namespace
				records(first: $first, after: $after) {
					edges {
						node {
							__typename
							... RecordListItem
						}
						cursor
					}
					pageInfo {
						hasNextPage
						endCursor
					}
					total
				}
			}
		}
	}
}
fragment RecordListItem on AspectRecord {
	id
	handle
	title
	createdAt
	updatedAt
	url(relative: false)
	data(format: ALL_BY_NAME)
	status {
		id
		label
	}
	createdBy {
		id
		name
		email
	}
}
`

